function renderProfileMenu(){try{var m=$('profileMenu');if(!m)return;var rows=[['edit-profile','user-round','تعديل الملف'],['change-pin','lock-keyhole','تغيير PIN'],['language','languages','اللغة'],['limits-go','gauge','حدود المعاملات'],['requested-go','inbox','المبالغ المطلوبة'],['qrshare-go','qr-code','مشاركة QR'],['camera-go','camera','التحقق بالكاميرا'],['kyc-go','id-card','توثيق KYC'],['faq-go','circle-help','الأسئلة الشائعة'],['support-go','headset','الدعم'],['terms-go','file-text','الشروط'],['privacy-go','shield-check','الخصوصية'],['about-go','info','عن بقش']];var h='';for(var i=0;i<rows.length;i++)h+='<button class="set-row" data-pm="'+rows[i][0]+'"><span style="display:flex;gap:10px;align-items:center"><span class="d-ic"><i data-lucide="'+rows[i][1]+'" class="w-4 h-4"></i></span>'+esc(rows[i][2])+'</span><i data-lucide="arrow-left" class="w-4 h-4"></i></button>';m.innerHTML=h;var bs=m.querySelectorAll('[data-pm]');for(var j=0;j<bs.length;j++)(function(bb){bb.onclick=function(){profileAct(bb.getAttribute('data-pm'));};})(bs[j]);refreshIcons();}catch(e){}}
function profileAct(k){if(k==='limits-go'){goto('limits');}else if(k==='requested-go'){goto('requested');}else if(k==='language'){setLang(state.lang==='ar'?'en':'ar');}else if(k==='qrshare-go'){openQrShare();}else if(k==='camera-go'){openPro('camera');}else if(k==='kyc-go'){openPro('kyc');}else if(k==='edit-profile'){openEditProfile();}else if(k==='change-pin'){openChangePin();}else{openInfoSheet(k.replace('-go',''));}}
function openEditProfile(){var nm=(state.user&&state.user.name)||'';openSheet('تعديل الملف','<label class="field-label">الاسم</label><input id="epName" class="field-input select-box" value="'+esc(nm)+'"><button class="btn-filled wfull" id="epSave" style="margin-top:10px">حفظ (demo)</button>');var b=$('epSave');if(b)b.onclick=function(){var v=$('epName')?$('epName').value.trim():'';if(v&&state.user)state.user.name=v;syncProfileHeader();closeSheet();toast('✓ demo');};}
