function doLogin(e){if(e&&e.preventDefault)e.preventDefault();var ph=$('phoneInput'),pi=$('pinInput');if(!ph||!pi)return;var pv=validatePhone(ph.value.trim()),qv=validatePin(pi.value.trim());showError('phoneShell','phoneError',pv.ok?'':pv.msg);showError('pinShell','pinError',qv.ok?'':qv.msg);if(!pv.ok||!qv.ok){showAlert('error','تحقق من الحقول');return;}hideAlert();setLoading(true);fetch('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({phone:pv.normalized,pin:pi.value.trim(),role:state.role})}).then(function(r){return r.json().catch(function(){return{};}).then(function(d){return{r:r,d:d};});}).then(function(x){if(!x.r.ok||!x.d.ok)throw new Error(x.d.message||'فشل الدخول');if(state.role==='cashier'){openPro('ccode');setLoading(false);state._pendingUser=x.d.user;return;}enterApp(x.d.user);}).catch(function(err){var pin=pi.value.trim();if(pv.core===DEMO_PHONE&&pin===DEMO_PIN){if(state.role==='cashier'){openPro('ccode');state._pendingUser={name:'متجر النور (تجريبي)',phone:pv.normalized,role:'cashier'};}else enterApp({name:'ضيف بقش',phone:pv.normalized,role:state.role});}else showAlert('error',err.message||'تعذّر الاتصال');}).then(function(){setLoading(false);});}
function doBioLogin(){try{var st=$('bioState');if(st)st.textContent='...';setTimeout(function(){if(st)st.textContent='✓';var ph=$('phoneInput'),pp=$('pinInput');if(ph&&!String(ph.value||'').trim())ph.value=DEMO_PHONE;if(pp&&!String(pp.value||'').trim()){pp.value=DEMO_PIN;}updatePinDots();doLogin();setTimeout(function(){if(st)st.textContent='جاهز';},2000);},900);}catch(e){}}
